-- CulinaLink Texas migration 006: DoorDash Drive v2 worker and Killeen-first delivery records.
CREATE TABLE IF NOT EXISTS platform_configuration(id bigserial PRIMARY KEY,config_key text UNIQUE NOT NULL,config_value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO platform_configuration(config_key,config_value) VALUES('LEGAL_HOME','{"city":"Killeen","state":"TX","county":"Bell","country":"US","market_code":"KILLEEN_TX"}'::jsonb) ON CONFLICT(config_key) DO UPDATE SET config_value=EXCLUDED.config_value,updated_at=now();
CREATE TABLE IF NOT EXISTS delivery_provider_integrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider text NOT NULL,environment text NOT NULL DEFAULT 'SANDBOX',credential_status text NOT NULL DEFAULT 'EXTERNAL_REQUIRED',webhook_status text NOT NULL DEFAULT 'EXTERNAL_REQUIRED',production_access_status text NOT NULL DEFAULT 'PROVIDER_APPROVAL_REQUIRED',home_market text NOT NULL DEFAULT 'KILLEEN_TX',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS delivery_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_user_id uuid,booking_id uuid REFERENCES bookings(id),provider text NOT NULL DEFAULT 'DOORDASH_DRIVE_V2',external_delivery_id text UNIQUE NOT NULL,environment text NOT NULL DEFAULT 'SANDBOX',home_market text NOT NULL DEFAULT 'KILLEEN_TX',pickup_address jsonb NOT NULL DEFAULT '{}',dropoff_address jsonb NOT NULL DEFAULT '{}',quote_payload jsonb,provider_payload jsonb,state text NOT NULL DEFAULT 'DRAFT',fee_cents integer CHECK(fee_cents IS NULL OR fee_cents>=0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS delivery_events(id bigserial PRIMARY KEY,delivery_job_id uuid REFERENCES delivery_jobs(id) ON DELETE CASCADE,provider_event text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',received_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_delivery_jobs_owner ON delivery_jobs(owner_user_id,created_at DESC);CREATE INDEX IF NOT EXISTS idx_delivery_jobs_state ON delivery_jobs(state,updated_at DESC);CREATE INDEX IF NOT EXISTS idx_delivery_events_job ON delivery_events(delivery_job_id,received_at DESC);
-- Runtime AppDeploy key-value tables are backfilled lazily per authenticated user. No existing booking, contractor, tax, AP, Rapid Pay or audit record is deleted or rewritten by this migration.